import "server-only";
import { createClient } from "@supabase/supabase-js";
import { createSupabaseServerClient } from "@/lib/supabase/server";
import { supabasePublishableKey, supabaseUrl } from "@/lib/supabase/config";
import { unauthorized } from "./http";
import { prisma } from "./prisma";

// Who is calling. Identity comes from Supabase Auth (a verified JWT); the role
// and organization come ONLY from our tables (memberships for staff/managers,
// tenants.user_id for tenants) — never from user_metadata, which users can edit.

export type Actor =
  | {
      kind: "member";
      userId: string;
      email: string | null;
      orgId: string;
      role: "manager" | "staff";
    }
  | {
      kind: "tenant";
      userId: string;
      email: string | null;
      orgId: string;
      tenantId: string;
    };

type AuthUser = { id: string; email: string | null };

const BEARER_PATTERN = /^Bearer\s+(\S+)$/i;

// Authorization: Bearer <access token> (how the graders' tests call the API).
// getUser(token) asks the Auth server to verify the token — not a local decode.
const userFromBearer = async (token: string): Promise<AuthUser | null> => {
  const supabase = createClient(supabaseUrl(), supabasePublishableKey(), {
    auth: {
      persistSession: false,
      autoRefreshToken: false,
      detectSessionInUrl: false,
    },
  });
  const { data, error } = await supabase.auth.getUser(token);
  if (error || !data.user) {
    return null;
  }
  return { id: data.user.id, email: data.user.email ?? null };
};

// The browser session cookie. getUser(), never getSession(): getSession trusts
// the cookie's contents without asking the Auth server.
const userFromCookie = async (): Promise<AuthUser | null> => {
  const supabase = await createSupabaseServerClient();
  const { data, error } = await supabase.auth.getUser();
  if (error || !data.user) {
    return null;
  }
  return { id: data.user.id, email: data.user.email ?? null };
};

const authUser = async (req?: Request): Promise<AuthUser | null> => {
  const header = req?.headers.get("authorization");
  if (header) {
    const match = BEARER_PATTERN.exec(header.trim());
    // A malformed Authorization header is not silently ignored in favour of
    // a cookie: the caller asked to authenticate with it, and it is invalid.
    return match?.[1] ? userFromBearer(match[1]) : null;
  }
  return userFromCookie();
};

/** Resolves the caller to an Actor, or null when there is no valid login or no role. */
export const getActor = async (req?: Request): Promise<Actor | null> => {
  const user = await authUser(req);
  if (!user) {
    return null;
  }
  const membership = await prisma.memberships.findUnique({
    where: { user_id: user.id },
    select: { org_id: true, role: true },
  });
  if (membership) {
    if (membership.role !== "manager" && membership.role !== "staff") {
      return null;
    }
    return {
      kind: "member",
      userId: user.id,
      email: user.email,
      orgId: membership.org_id,
      role: membership.role,
    };
  }
  const tenant = await prisma.tenants.findUnique({
    where: { user_id: user.id },
    select: { id: true, org_id: true },
  });
  if (tenant) {
    return {
      kind: "tenant",
      userId: user.id,
      email: user.email,
      orgId: tenant.org_id,
      tenantId: tenant.id,
    };
  }
  return null;
};

/** getActor or 401. */
export const requireActor = async (req?: Request): Promise<Actor> => {
  const actor = await getActor(req);
  if (!actor) {
    throw unauthorized();
  }
  return actor;
};
import "server-only";
import type { leases, payments } from "@/generated/prisma/client";
import type { Actor } from "./auth";
import { forbidden, notFound } from "./http";
import { prisma } from "./prisma";
import type { Tx } from "./allocation";

// Record visibility (-> 404) and role checks (-> 403), shared by every service.
// Prisma bypasses RLS, so these ARE the authorization for server code. No
// next/headers here: seed scripts and tests call services with a hand-made Actor.

type Db = Tx | typeof prisma;
export type MemberActor = Extract<Actor, { kind: "member" }>;
export type ManagerActor = MemberActor & { role: "manager" };

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export const isUuid = (value: unknown): value is string =>
  typeof value === "string" && UUID_PATTERN.test(value);

// The org filter is part of the query, so a record in another organization is
// indistinguishable from one that does not exist.
const leaseScope = (actor: Actor) =>
  actor.kind === "tenant"
    ? { org_id: actor.orgId, tenant_id: actor.tenantId }
    : { org_id: actor.orgId };

/** The lease if the actor may see it, else null (bad id, other org, other tenant). */
export const findVisibleLease = async (
  actor: Actor,
  leaseId: string,
  tx: Db = prisma,
): Promise<leases | null> => {
  if (!isUuid(leaseId)) {
    return null;
  }
  return tx.leases.findFirst({ where: { id: leaseId, ...leaseScope(actor) } });
};

export const requireVisibleLease = async (
  actor: Actor,
  leaseId: string,
  tx: Db = prisma,
): Promise<leases> => {
  const lease = await findVisibleLease(actor, leaseId, tx);
  if (!lease) {
    throw notFound();
  }
  return lease;
};

/** The payment if the actor may see it (tenant: only payments on their own leases). */
export const findVisiblePayment = async (
  actor: Actor,
  paymentId: string,
  tx: Db = prisma,
): Promise<payments | null> => {
  if (!isUuid(paymentId)) {
    return null;
  }
  return tx.payments.findFirst({
    where: {
      id: paymentId,
      org_id: actor.orgId,
      ...(actor.kind === "tenant"
        ? { leases: { tenant_id: actor.tenantId } }
        : {}),
    },
  });
};

export const requireVisiblePayment = async (
  actor: Actor,
  paymentId: string,
  tx: Db = prisma,
): Promise<payments> => {
  const payment = await findVisiblePayment(actor, paymentId, tx);
  if (!payment) {
    throw notFound();
  }
  return payment;
};

// Assertion signatures need an explicit type annotation on an arrow function.
export const requireMember: (actor: Actor) => asserts actor is MemberActor = (
  actor,
) => {
  if (actor.kind !== "member") {
    throw forbidden();
  }
};

export const requireManager: (actor: Actor) => asserts actor is ManagerActor = (
  actor,
) => {
  if (actor.kind !== "member" || actor.role !== "manager") {
    throw forbidden();
  }
};
import "server-only";
import { unstable_rethrow } from "next/navigation";
import { NextResponse } from "next/server";
import { z } from "zod";

// Route-handler plumbing: one error shape ({ error }) and one place that maps
// thrown errors to status codes (docs/TASK.md sections 6 and 7).

type RouteFn<C> = (req: Request, ctx: C) => Promise<Response>;

export class HttpError extends Error {
  readonly status: number;

  constructor(status: number, message: string) {
    super(message);
    this.name = "HttpError";
    this.status = status;
  }
}

export const badRequest = (message: string) => new HttpError(400, message);
export const unauthorized = () => new HttpError(401, "Unauthorized");
export const forbidden = () => new HttpError(403, "Forbidden");
export const notFound = () => new HttpError(404, "Not found");
export const conflict = (message: string) => new HttpError(409, message);
export const unprocessable = (message: string) => new HttpError(422, message);

export const json = (data: unknown, status = 200) =>
  NextResponse.json(data, { status });

export const jsonError = (status: number, message: string) =>
  NextResponse.json({ error: message }, { status });

// "amountSen: Invalid input: expected number" — names the first failing field,
// never echoes the submitted value.
const describeZodError = (error: z.ZodError): string => {
  const issue = error.issues[0];
  if (!issue) {
    return "Invalid input";
  }
  const path = issue.path.map(String).join(".");
  return path ? `${path}: ${issue.message}` : issue.message;
};

// Wraps a route handler. Generic over the context so routes keep Next's typing,
// e.g. handle<RouteContext<"/api/leases/[leaseId]">>(async (req, ctx) => …).
export const handle =
  <C = unknown>(fn: RouteFn<C>): RouteFn<C> =>
  async (req, ctx) => {
    try {
      return await fn(req, ctx);
    } catch (error) {
      // Let Next's own control-flow errors (redirect, notFound, …) through.
      unstable_rethrow(error);
      if (error instanceof HttpError) {
        return jsonError(error.status, error.message);
      }
      if (error instanceof z.ZodError) {
        return jsonError(400, describeZodError(error));
      }
      // Message only: never log request bodies, tokens or the gateway key.
      console.error(
        "Unhandled route error:",
        error instanceof Error ? error.message : "non-Error thrown",
      );
      return jsonError(500, "Internal error");
    }
  };

export const readJson = async <T>(
  req: Request,
  schema: z.ZodType<T>,
): Promise<T> => {
  let body: unknown;
  try {
    body = await req.json();
  } catch {
    throw badRequest("Invalid JSON body");
  }
  const result = schema.safeParse(body);
  if (!result.success) {
    throw badRequest(describeZodError(result.error));
  }
  return result.data;
};

// Reads a JSON body WITHOUT validating it, for routes whose service must run
// its 404/403 checks before input validation (401 → 404 → 403 → 400). Invalid
// JSON becomes `undefined`, which the service's zod schema rejects with 400.
export const readJsonBody = async (req: Request): Promise<unknown> => {
  try {
    return await req.json();
  } catch {
    return undefined;
  }
};
import { createServerClient } from "@supabase/ssr";
import { NextResponse, type NextRequest } from "next/server";
import { supabasePublishableKey, supabaseUrl } from "@/lib/supabase/config";

// Refreshes the Supabase session cookie on every request. Route protection
// is NOT done here — every page and Server Action authorizes on its own.
export const proxy = async (request: NextRequest) => {
  let response = NextResponse.next({ request });

  const supabase = createServerClient(supabaseUrl(), supabasePublishableKey(), {
    cookies: {
      getAll: () => request.cookies.getAll(),
      setAll: (cookiesToSet) => {
        cookiesToSet.forEach(({ name, value }) =>
          request.cookies.set(name, value),
        );
        response = NextResponse.next({ request });
        cookiesToSet.forEach(({ name, value, options }) =>
          response.cookies.set(name, value, options),
        );
      },
    },
  });

  await supabase.auth.getUser();

  return response;
};

export const config = {
  matcher: [
    "/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp)$).*)",
  ],
};
import "server-only";
import { createClient, type SupabaseClient } from "@supabase/supabase-js";
import { supabaseUrl } from "@/lib/supabase/config";

// Supabase client with the SECRET key: bypasses RLS and Storage policies.
// Server-only (the import above makes a client-bundle import fail the build);
// used only for slip storage operations, after the caller is authorized.

let adminClient: SupabaseClient | null = null;

const secretKey = (): string => {
  const key = process.env.SUPABASE_SECRET_KEY;
  if (!key) {
    throw new Error(
      "Missing required environment variable: SUPABASE_SECRET_KEY",
    );
  }
  return key;
};

export const supabaseAdmin = (): SupabaseClient => {
  if (!adminClient) {
    adminClient = createClient(supabaseUrl(), secretKey(), {
      auth: {
        persistSession: false,
        autoRefreshToken: false,
        detectSessionInUrl: false,
      },
    });
  }
  return adminClient;
};
import "server-only";
import { PrismaPg } from "@prisma/adapter-pg";
import { PrismaClient } from "@/generated/prisma/client";

type GlobalWithPrisma = typeof globalThis & { prisma?: PrismaClient };

const globalForPrisma: GlobalWithPrisma = globalThis;

const createPrismaClient = () => {
  const connectionString = process.env.DATABASE_URL;
  if (!connectionString) {
    throw new Error("Missing required environment variable: DATABASE_URL");
  }
  return new PrismaClient({ adapter: new PrismaPg({ connectionString }) });
};

// Connects as the `postgres` role, which BYPASSES Row Level Security.
// Every caller must authorize the user first (see CLAUDE.md → Auth).
export const prisma = globalForPrisma.prisma ?? createPrismaClient();

if (process.env.NODE_ENV !== "production") {
  globalForPrisma.prisma = prisma;
}
import { createBrowserClient } from "@supabase/ssr";
import { supabasePublishableKey, supabaseUrl } from "./config";

export const createSupabaseBrowserClient = () =>
  createBrowserClient(supabaseUrl(), supabasePublishableKey());
// NEXT_PUBLIC_* values must be read as literal `process.env.X` so Next.js can
// inline them into the browser bundle.
const requireValue = (name: string, value: string | undefined): string => {
  if (!value) {
    throw new Error(`Missing required environment variable: ${name}`);
  }
  return value;
};

export const supabaseUrl = () =>
  requireValue(
    "NEXT_PUBLIC_SUPABASE_URL",
    process.env.NEXT_PUBLIC_SUPABASE_URL,
  );

export const supabasePublishableKey = () =>
  requireValue(
    "NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY",
    process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY,
  );
import "server-only";
import { createServerClient } from "@supabase/ssr";
import { cookies } from "next/headers";
import { supabasePublishableKey, supabaseUrl } from "./config";

// Acts as the signed-in user (their JWT), so RLS applies to every query.
export const createSupabaseServerClient = async () => {
  const cookieStore = await cookies();

  return createServerClient(supabaseUrl(), supabasePublishableKey(), {
    cookies: {
      getAll: () => cookieStore.getAll(),
      setAll: (cookiesToSet) => {
        try {
          cookiesToSet.forEach(({ name, value, options }) =>
            cookieStore.set(name, value, options),
          );
        } catch {
          // Called from a Server Component, where cookies are read-only.
          // proxy.ts refreshes the session on every request instead.
        }
      },
    },
  });
};

