console.log("staff direct upload of MZ bytes as .pdf:", up.status, (await up.text()).slice(0, 80));
const c = new pg.Client({ connectionString: DBURL }); await c.connect();
const lease = (await c.query(`select org_id from leases where id=$1`, [PL])).rows[0];
const staffId = "cbf474b7-ee52-4761-a6f0-33eab730572f";
const tryPath = async (label, path) => {
  await c.query("begin");
  try {
    await c.query(`insert into payments(org_id, lease_id, amount_sen, method, status, received_at, slip_path, recorded_by) values ($1,$2,1,'bank_transfer','pending_verification',now(),$3,$4)`, [lease.org_id, PL, path, staffId]);
    console.log(label, "-> ACCEPTED by DB");
  } catch (e) { console.log(label, "-> refused", e.code, e.message.slice(0, 90)); }
  finally { await c.query("rollback"); }
};
await tryPath("nonexistent", `${NW}/nope.pdf`);
await tryPath("traversal", `${NW}/../${BETA}/x.pdf`);
await tryPath("other org", `${BETA}/x.pdf`);
await tryPath("MZ-bytes file uploaded directly", exeName);
const meta = (await c.query(`select metadata->>'mimetype' m, metadata->>'size' s from storage.objects where name=$1`, [exeName])).rows[0];
console.log("stored object metadata:", meta);
await c.end();
const SK = process.env.SK;
const del = await fetch(`${S}/object/payment-slips`, { method: "DELETE", headers: { apikey: SK, authorization: `Bearer ${SK}`, "content-type": "application/json" }, body: JSON.stringify({ prefixes: [exeName] }) });
console.log("cleanup", del.status);

