const A = "http://127.0.0.1:3457";
const ID = {
  approve: "40e2cecea51ba3f4d710393a792fc11b4a3c56d84e",
  reject: "6079a45f3dd6037a09cc1d71b1011a917f579571da",
  void: "6082ddb36874626607c3ae4cd53a07a62610c5661c",
  record: "60a38212c52f73ab2cea16d4d9f81f378117f9964a",
  createLease: "405bbff909321994d145d7ea15f356cfc73f1a5055",
  payNow: "408182c8000ce204d9333932a161b1d82d95c7fa23",
};
const AIS_L = "15d44020-755e-444d-90cf-395fdda86f2a", PROBE_L = "6a8681d8-82d4-4427-9279-204ca3c83c1b";
const AIS_PAY_CASH = "099c4ae9-cf52-4656-841f-d5a3f8f1f478", PROBE_REJ = "f5a9a846-276d-4842-97a7-679507827ef8";
const BETA_UNIT = "48acf02f-c067-4abe-8257-6ebeb0e1f20f", PROBE_T = "96e34e12-a2d5-4cbc-bbd4-5c75c7b7e418", NW_UNIT_AIS = "7abb0f99-6688-4f02-a05a-9f68aecc6ab5";
const who = { anon: { cookie: "" } };
for (const [k, e] of [["probe", "probe@northwind.test"], ["aisyah", "aisyah@northwind.test"], ["staff", "staff@northwind.test"], ["mgr", "manager@northwind.test"], ["betamgr", "manager@beta.test"]]) who[k] = await session(e);
const out = [];
const act = async (label, w, id, page, args, { origin = A, form } = {}) => {
  const headers = { "next-action": id, origin, accept: "text/x-component", ...(who[w].cookie ? { cookie: who[w].cookie } : {}) };
  let body;
  if (form) { body = form; } else { headers["content-type"] = "text/plain;charset=UTF-8"; body = JSON.stringify(args); }
  const r = await fetch(A + page, { method: "POST", headers, body, redirect: "manual" });
  const t = await r.text();
  const line = t.split("\n").find((l) => l.startsWith("1:")) ?? t.slice(0, 160);
  out.push({ label, w, status: r.status, result: line.slice(0, 120) });
};
const lease = { unitId: NW_UNIT_AIS, tenantId: PROBE_T, startDate: "2031-01-01", endDate: "2031-12-31", monthlyRent: "1000.00", deposit: "" };
const recordForm = (leaseId) => { const f = new FormData(); f.append("0", JSON.stringify([leaseId, "$K1"])); f.append("1_amount", "1.00"); f.append("1_method", "cash"); f.append("1_receivedAt", "2026-10-20T10:00"); return f; };
for (const w of ["anon", "probe", "staff", "betamgr"]) {
  await act("approve probe rejected pmt", w, ID.approve, `/leases/${PROBE_L}`, [PROBE_REJ]);
  await act("void aisyah cash pmt", w, ID.void, `/leases/${AIS_L}`, [AIS_PAY_CASH, { reason: "audit probe" }]);
  await act("reject aisyah cash pmt", w, ID.reject, `/leases/${AIS_L}`, [AIS_PAY_CASH, { reason: "audit probe" }]);
  await act("createLease NW unit", w, ID.createLease, `/leases/new`, [lease]);
  await act("record cash on probe lease", w, ID.record, `/leases/${PROBE_L}`, null, { form: recordForm(PROBE_L) });
  await act("payNow probe lease", w, ID.payNow, `/portal`, [PROBE_L]);
}
await act("createLease BETA unit", "mgr", ID.createLease, `/leases/new`, [{ ...lease, unitId: BETA_UNIT }]);
await act("payNow other tenant lease", "aisyah", ID.payNow, `/portal`, [PROBE_L]);
await act("payNow from wrong page (/login)", "probe", ID.payNow, `/login`, [PROBE_L]);
await act("cross-origin approve (CSRF)", "mgr", ID.approve, `/leases/${PROBE_L}`, [PROBE_REJ], { origin: "https://evil.example" });
console.table(out);

